from math import gcd, isqrt

def count_reps_for_x(x, k_mod):
    # Count valid representations for a single x.
    # We use the factor-pair bijection: x = (m-n)(m+n) with a = m-n, b = m+n.
    # We iterate a over divisors up to sqrt(x), set b = x//a, enforce a<=b.
    # Parity: a and b must have the same parity so that m, n are integers.
    # Congruence: a = m-n must be divisible by k_mod.
    # Coprimality: gcd(m, n) = 1 checked directly after constructing m, n.
    cnt = 0
    lim = isqrt(x)
    for a in range(1, lim + 1):
        if x % a != 0:
            continue
        b = x // a
        # a is m-n (the smaller factor), b is m+n (the larger factor)
        if (a & 1) != (b & 1):
            continue
        if a % k_mod != 0:
            continue
        m = (a + b) // 2
        n = (b - a) // 2
        # Ensure m > n >= 0 automatically holds for a > 0, b >= a
        if gcd(m, n) != 1:
            continue
        cnt += 1
    return cnt

def solve(n_max, k_mod, min_reps):
    ans = 0
    for x in range(1, n_max + 1):
        if count_reps_for_x(x, k_mod) >= min_reps:
            ans += 1
    return ans

# Try random parameters ensuring nontriviality
for _ in range(64):
    n_max = rng.randint(800, 6000)
    k_mod = rng.randint(2, 12)
    # Slightly higher min_reps for larger ranges
    if n_max < 1500:
        min_reps = rng.choice([2, 3])
    else:
        min_reps = rng.choice([2, 3, 4])
    ans = solve(n_max, k_mod, min_reps)
    # Require a nontrivial proportion of qualifying x
    if ans == 0 or ans == n_max:
        continue
    frac = ans / n_max
    if 0.05 <= frac <= 0.95:
        return {'n_max': n_max, 'k_mod': k_mod, 'min_reps': min_reps}
# Fallback values chosen to be reasonably nontrivial
return {'n_max': 1500, 'k_mod': 3, 'min_reps': 2}

